import unittest

from hourglass.models import Span
from hourglass.rounding import round_spans


class RoundingTests(unittest.TestCase):
    def test_label(self):
        spans = [Span(9 * 60, 17 * 60 + 15)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        spans = [Span(9 * 60 + 7, 17 * 60 + 8)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [Span(7, 67)]
        self.assertEqual(
            round_spans(spans, 10), ["00:10-01:10 (1h 0m)"]
        )

    def test_empty(self):
        self.assertEqual(round_spans([], 5), [])

    def test_bad_steps(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)
